Assuming the usual includes and using namespace std, what does this program print?

struct T { T(int n) { cout << n; } };
struct S { T x, y; S() : y(2), x(1) {} };
int main() { S s; }

Assuming the usual includes and using namespace std, what does this program print?

struct B { B() { f(); } virtual void f() { cout << 1; } };
struct D : B { void f() override { cout << 2; } };
int main() { D d; }
